const items = $input.all();
const fila = items.find(i => i.json && i.json.valor !== undefined);
// Si nunca se toco el interruptor del panel, no hay fila todavia: por defecto el bot esta activo (igual que en App.jsx).
const activo = fila ? fila.json.valor === 'true' : true;
return [{ json: { botActivo: activo } }];

const items = $input.all();
const encontrados = items
  .map(i => i.json)
  .filter(item => item && item.id !== undefined && item.id !== null);

if (encontrados.length > 0) {
  return [{ json: { existe: true, clienteId: encontrados[0].id, nombreGuardado: encontrados[0].nombre } }];
}
return [{ json: { existe: false } }];

const servicios = $('Traer servicios1').all().map(i => i.json);
const barberos = $('Traer barberos1').all().map(i => i.json);

// ===== Parser de horario_texto (portado igual que en la web, src/lib/text.js) =====
function parseHorarioBarbero(horario) {
  if (!horario || typeof horario !== 'string') return null;
  const txt = horario.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  const mapa = {
    lun: 1, lunes: 1,
    mar: 2, martes: 2,
    mie: 3, miercoles: 3,
    jue: 4, jueves: 4,
    vie: 5, viernes: 5,
    sab: 6, sabado: 6,
    dom: 0, domingo: 0,
  };

  const conBreak = txt.match(/(.+?)\s+(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})\s+break\s+(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  if (conBreak) {
    const [, diasTxt, hIni, mIni, hFin, mFin, hBreakIni, mBreakIni, hBreakFin, mBreakFin] = conBreak;
    const dias = diasTxt.split(/\s*,\s*|\s+y\s+/).map(s => s.trim()).filter(Boolean);
    const atencion = { ini: Number(hIni) * 60 + Number(mIni), fin: Number(hFin) * 60 + Number(mFin) };
    const breakBlock = { ini: Number(hBreakIni) * 60 + Number(mBreakIni), fin: Number(hBreakFin) * 60 + Number(mBreakFin), break: true };
    const result = {};
    for (const d of dias) if (mapa[d] !== undefined) result[mapa[d]] = [atencion, breakBlock];
    return Object.keys(result).length ? result : null;
  }

  const rangoDias = txt.match(/([a-z]+)\s+a\s+([a-z]+)\s+(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  if (rangoDias) {
    const [, dIni, dFin, hIni, mIni, hFin, mFin] = rangoDias;
    const ini = mapa[dIni], fin = mapa[dFin];
    if (ini === undefined || fin === undefined) return null;
    const bloque = { ini: Number(hIni) * 60 + Number(mIni), fin: Number(hFin) * 60 + Number(mFin) };
    const result = {};
    if (ini <= fin) { for (let d = ini; d <= fin; d++) result[d] = [bloque]; }
    else { for (let d = ini; d <= 6; d++) result[d] = [bloque]; for (let d = 0; d <= fin; d++) result[d] = [bloque]; }
    return result;
  }

  const varios = txt.match(/((?:[a-z]+\s*,\s*)*(?:[a-z]+\s*y\s+)[a-z]+)\s+(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  if (varios) {
    const [, diasTxt, hIni, mIni, hFin, mFin] = varios;
    const nombres = diasTxt.split(/\s*,\s*|\s+y\s+/).map(s => s.trim()).filter(Boolean);
    const bloque = { ini: Number(hIni) * 60 + Number(mIni), fin: Number(hFin) * 60 + Number(mFin) };
    const result = {};
    for (const n of nombres) if (mapa[n] !== undefined) result[mapa[n]] = [bloque];
    return Object.keys(result).length ? result : null;
  }

  const unDia = txt.match(/([a-z]+)\s+(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  if (unDia) {
    const [, d, hIni, mIni, hFin, mFin] = unDia;
    if (mapa[d] === undefined) return null;
    return { [mapa[d]]: [{ ini: Number(hIni) * 60 + Number(mIni), fin: Number(hFin) * 60 + Number(mFin) }] };
  }

  return null;
}

function minAHora(min) {
  const h = String(Math.floor(min / 60)).padStart(2, '0');
  const m = String(min % 60).padStart(2, '0');
  return `${h}:${m}`;
}

const DIAS_ES = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];

// ===== Contexto de servicios =====
let contexto = 'SERVICIOS Y PRECIOS:\n';
for (const s of servicios) contexto += `- ${s.nombre} (id ${s.id}): ${s.duracion_min} min, $${s.precio}\n`;

// ===== Habilidades: que servicios puede hacer cada barbero =====
// Un barbero sin habilidades cargadas (null o array vacio) hace CUALQUIER
// servicio. Si tiene habilidades cargadas, son las UNICAS que puede hacer.
function generarIdHabilidad(nombre) {
  return nombre.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '');
}
function parseHabilidades(str) {
  if (!str) return [];
  try { return JSON.parse(str); } catch { return []; }
}
const serviciosPorId = Object.fromEntries(servicios.map(s => [generarIdHabilidad(s.nombre), s.nombre]));

// ===== Contexto de barberos (horario + que servicios hace cada uno) =====
contexto += '\nBARBEROS:\n';
for (const b of barberos) {
  const habilidades = parseHabilidades(b.habilidades);
  const queHace = habilidades.length === 0
    ? 'hace TODOS los servicios de la lista'
    : `SOLO hace: ${habilidades.map(h => serviciosPorId[h] || h).join(', ')}`;
  contexto += `- ${b.nombre} (id ${b.id}): ${b.horario_texto || 'sin horario cargado'} — ${queHace}\n`;
}

// ===== Calendario de los proximos 3 dias, YA CALCULADO (no lo calcules vos, Agente) =====
const hoyDate = new Date();
let calendario = '\nCALENDARIO DE LOS PROXIMOS 3 DIAS (usa esto tal cual para saber que dia de la semana es cada fecha y quien trabaja ese dia; NUNCA calcules vos el dia de la semana de una fecha, aunque te parezca facil. Para fechas mas lejanas, usa la herramienta consultar_disponibilidad en vez de asumir):\n';

for (let i = 0; i < 3; i++) {
  const d = new Date(hoyDate);
  d.setDate(d.getDate() + i);
  const fechaStr = d.toISOString().slice(0, 10);
  const diaSemana = d.getDay();
  const nombreDia = DIAS_ES[diaSemana];

  calendario += `${fechaStr} (${nombreDia}): `;

  const partesBarberos = [];
  for (const b of barberos) {
    const mapa = parseHorarioBarbero(b.horario_texto);
    const bloques = mapa ? (mapa[diaSemana] || []) : [];
    const trabajo = bloques.filter(x => !x.break);
    const breaks = bloques.filter(x => x.break);

    if (trabajo.length === 0) {
      partesBarberos.push(`${b.nombre} no trabaja`);
    } else {
      const rangos = trabajo.map(t => `${minAHora(t.ini)}-${minAHora(t.fin)}`).join(', ');
      const breakTxt = breaks.length ? ` (break ${breaks.map(x => `${minAHora(x.ini)}-${minAHora(x.fin)}`).join(', ')})` : '';
      partesBarberos.push(`${b.nombre} ${rangos}${breakTxt}`);
    }
  }
  calendario += partesBarberos.join(' | ') + '\n';
}

contexto += calendario;

const fechaHoy = hoyDate.toISOString().slice(0, 10);

return [{ json: {
  contextoNegocio: contexto,
  fechaHoy,
  clienteId: $('Guardar mensaje entrante1').first().json.cliente_id,
  telefono: $('Extraer datos1').first().json.telefono,
  texto: $('Extraer datos1').first().json.texto,
  nombre: $('Extraer datos1').first().json.nombre,
  remoteJid: $('Extraer datos1').first().json.remoteJid
} }];
